fn is_non_prime(n: u64) -> bool {
    // For n >= 2, check for a divisor k with 2 <= k < n.
    // If any divide n evenly, return true (non-prime).
    // Otherwise, return false (prime).
    //
    // To optimize, check divisors only up to sqrt(n).

    if n == 2 {
        return false; // 2 is prime
    }

    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true; // found a non-trivial divisor
        }
    }
    false
}